functionMap["onAttackEntity"] = function(entityId)
    if GameType == "g1046" and GameType == "g1063"  and GameType == "g1064" then
        return
    end
    local entity = EntityCache:getEntity(entityId)
    if entity == nil then
        return
    end
    if entity.type == EntityType.Creature then
        local lua_player = PlayerManager:getClientPlayer()
        lua_player:sendPacket({
            pid = "OnAttackEntity",
            entityId = EntityCache:getServerId(entityId)
        })
    end
end

